 "content": "from collections import Counter


def transform(grid):
    """Decode a lattice of colored corner markers into one value per tile."""
    h, w = len(grid), len(grid[0])
    marker_colors = {7, 8}
    row_nodes = [r for r in range(h) if any(grid[r][c] in marker_colors for c in range(w))]
    col_nodes = [c for c in range(w) if any(grid[r][c] in marker_colors for r in range(h))]
    if len(row_nodes) < 2 or len(col_nodes) < 2:
        raise ValueError("Could not locate marker lattice")

    out = []
    for ri in range(len(row_nodes) - 1):
        row = []
        r0, r1 = row_nodes[ri], row_nodes[ri + 1]
        for ci in range(len(col_nodes) - 1):
            c0, c1 = col_nodes[ci], col_nodes[ci + 1]
            corners = (grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1])
            if corners[0] in marker_colors and all(v == corners[0] for v in corners):
                row.append(corners[0])
            else:
                interior = [grid[r][c] for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)]
                if not interior:
                    raise ValueError("Tile has no interior")
                row.append(Counter(interior).most_common(1)[0][0])
        out.append(row)
    return out


